def validate_payload(payload: dict) -> dict:
    """Require account_id and a positive integer amount in cents."""
    account_id = payload.get("account_id")
    amount = payload.get("amount")
    if not isinstance(account_id, str) or not account_id.strip():
        raise ValidationError("account_id must be a nonempty string")
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        raise ValidationError("amount must be a positive integer")
    return {"account_id": account_id.strip(), "amount": amount}

def create_transfer(payload: dict, service: TransferService) -> dict:
    """Validate incoming transfer data before it reaches the service layer."""
    transfer = validate_payload(payload)
    return service.transfer(transfer)

class TransferService:
    """Coordinates a transfer without owning HTTP or database details."""

    def __init__(self, store: LedgerStore):
        self.store = store

    def transfer(self, payload: dict) -> dict:
        """Persist an accepted transfer and return its receipt."""
        receipt = self.store.append_transfer(payload)
        return {"receipt_id": receipt, "accepted": True}

def transfer(self, payload: dict) -> dict:
    """Persist an accepted transfer and return its receipt."""
    receipt = self.store.append_transfer(payload)
    return {"receipt_id": receipt, "accepted": True}

def test_receipt_is_returned():
    result = TransferService(LedgerStore()).transfer({"account_id": "a", "amount": 10})
    assert result == {"receipt_id": "receipt-1", "accepted": True}

def test_zero_amount_rejected():
    try:
        validate_payload({"account_id": "a", "amount": 0})
    except ValidationError:
        return
    raise AssertionError("expected validation failure")

def append_transfer(self, payload: dict) -> str:
    self.entries.append(dict(payload))
    return f"receipt-{len(self.entries)}"

